"""Embedding helpers used by the native (LangChain-free) vector stores.

This module replaces ``_langchain_embedding_client_adapter.py`` (removed as
part of ENG-1220 / ENG-2876). It provides:

* the Langfuse tracing metadata context helpers that were previously coupled
  to the LangChain ``Embeddings`` adapter, and
* thin ``embed_query`` / ``aembed_query`` helpers that call an
  :class:`~rasa.shared.providers.embedding.embedding_client.EmbeddingClient`
  directly.
"""

from __future__ import annotations

from contextlib import contextmanager
from contextvars import ContextVar
from typing import TYPE_CHECKING, Any, Dict, Iterator, List

if TYPE_CHECKING:
    from rasa.shared.providers.embedding.embedding_client import EmbeddingClient

# Context variable to store embedding metadata for Langfuse tracing.
# This allows metadata to be set per-call without threading it through every
# vector-store method signature.
_embedding_metadata: ContextVar[Dict[str, Any] | None] = ContextVar(
    "embedding_metadata", default=None
)


@contextmanager
def embedding_metadata_context(metadata: Dict[str, Any]) -> Iterator[None]:
    """Context manager to set embedding metadata for a block of code.

    This context manager automatically sets and clears metadata, ensuring it
    is properly cleaned up even if an exception occurs. It works correctly with
    async code.

    Args:
        metadata: Dictionary of metadata to pass to embedding calls.
    """
    token = _embedding_metadata.set(metadata)
    try:
        yield
    finally:
        _embedding_metadata.reset(token)


def _metadata_kwargs() -> Dict[str, Any]:
    metadata = _embedding_metadata.get()
    return {"metadata": metadata} if metadata else {}


def embed_query(client: "EmbeddingClient", text: str) -> List[float]:
    """Embed a single query string synchronously via an ``EmbeddingClient``.

    Forwards any Langfuse tracing metadata set through
    :func:`embedding_metadata_context`.
    """
    response = client.embed(documents=[text], **_metadata_kwargs())
    return response.data[0]


async def aembed_query(client: "EmbeddingClient", text: str) -> List[float]:
    """Embed a single query string asynchronously via an ``EmbeddingClient``.

    Forwards any Langfuse tracing metadata set through
    :func:`embedding_metadata_context`.
    """
    response = await client.aembed(documents=[text], **_metadata_kwargs())
    return response.data[0]


def embed_documents(client: "EmbeddingClient", texts: List[str]) -> List[List[float]]:
    """Embed a batch of documents synchronously via an ``EmbeddingClient``."""
    response = client.embed(documents=texts, **_metadata_kwargs())
    return response.data
